  match goal with
  | K : shk ?m ?b ?X, ACC : acc asegs ?m ?a ?n |- evt _ _ (MS _ _ (if _ then _ else _) _ _ ?m _) =>
      let OK := fresh "SHOK" in
      assert (OK : sh_ok b (X + 8 - 1)) by (apply (shk_ok m a n X 8 b ACC K); lia);
